        return 0 <= x < w and 0 <= y < h

    def blocked(x, y):
        return (x, y) in obstacles

    moves = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    cx, cy = (w - 1) / 2.0, (h - 1) / 2.0

    def center_bias(x, y):
        return abs(x - cx) + abs(y - cy)

    targets = []
    if unclaimed:
        for tx, ty in unclaimed:
            if not inb(tx, ty) or blocked(tx, ty):
                continue
            targets.append((tx, ty))
