            targets.sort(key=lambda p: center_bias(p[0], p[1]))
            targets = targets[:10]
    if not targets:
        for tx, ty in opp_terr:
            if inb(tx, ty) and not blocked(tx, ty):
                targets.append((tx, ty))
        if len(targets) > 10:
            targets.sort(key=lambda p: center_bias(p[0], p[1]))
            targets = targets[:10]
    if not targets:
        for tx, ty in self_terr:
            if inb(tx, ty) and not blocked(tx, ty):
                targets.append((tx, ty))
        if not targets:
            targets = [(ox, oy), (sx, sy)]

    def score_cell(x, y):
